import{bV as t,aL as o,u as s,G as d}from"./chunks/framework.DvBUyM1S.js";const h=JSON.parse('{"title":"VS Code settings.json 审查与优化清单（冲突检测 + 死配置清理 + 新设置项补齐）","description":"","frontmatter":{"id":"PB-20260901-001","type":"playbook","title":"VS Code settings.json 审查与优化清单（冲突检测 + 死配置清理 + 新设置项补齐）","tags":["vscode","settings","dx","audit"],"status":"verified","source":"conversation:2026-09-01","created":"2026-09-01T00:00:00.000Z","updated":"2026-09-01T00:00:00.000Z"},"headers":[],"relativePath":"playbooks/vscode-settings-audit.md","filePath":"playbooks/vscode-settings-audit.md"}'),a={name:"playbooks/vscode-settings-audit.md"};function i(n,e,l,c,r,p){return o(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="vs-code-settings-json-审查与优化清单" tabindex="-1">VS Code settings.json 审查与优化清单 <a class="header-anchor" href="#vs-code-settings-json-审查与优化清单" aria-label="Permalink to &quot;VS Code settings.json 审查与优化清单&quot;">​</a></h1><blockquote><p>用途：给一份几百行的 <code>settings.json</code>（通常是 antfu / 网络模板的复制品）做体检， 找出<strong>互相打架的配置</strong>、<strong>对当前 OS 无效的死配置</strong>、<strong>被注释掉的收益项</strong>， 并按段落补齐新版 VS Code 的设置项。 约束：只改值 / 在段落内插入，不重排已有条目（避免 diff 爆炸、便于回滚）。</p></blockquote><h2 id="_1-先查配置冲突-唯一会-静默失效-的一类-优先级最高" tabindex="-1">1. 先查配置冲突（唯一会&quot;静默失效&quot;的一类，优先级最高） <a class="header-anchor" href="#_1-先查配置冲突-唯一会-静默失效-的一类-优先级最高" aria-label="Permalink to &quot;1. 先查配置冲突（唯一会&quot;静默失效&quot;的一类，优先级最高）&quot;">​</a></h2><p>排查口诀：<strong>凡是 <code>xxx.enable: false</code> 的开关，都要全局搜它对应的引用点。</strong></p><table tabindex="0"><thead><tr><th>开关</th><th>冲突表现</th><th>修法</th></tr></thead><tbody><tr><td><code>prettier.enable: false</code></td><td>插件整体停用，所有 <code>editor.defaultFormatter: esbenp.prettier-vscode</code> 变死配置（官方要求改后重启 VS Code）</td><td>二选一：删掉该行；或把所有 <code>[lang].editor.defaultFormatter</code> 换成 ESLint / 内置 formatter</td></tr><tr><td><code>eslint.format.enable: false</code></td><td>若某语言 <code>defaultFormatter</code> 指向 ESLint，该语言格式化失效</td><td>同上，保持两者指向一致</td></tr><tr><td><code>editor.formatOnSave: false</code> + 各语言 <code>codeActionsOnSave</code></td><td>不冲突，但要确认 <code>source.fixAll.*</code> 的值是 <code>&quot;always&quot;</code> / <code>&quot;explicit&quot;</code> / <code>&quot;never&quot;</code> 而不是 <code>true</code> / <code>false</code></td><td>布尔值已被废弃语义，统一改三态字符串</td></tr><tr><td><code>files.eol</code> vs 项目 lint / prettier <code>endOfLine</code></td><td>与团队规范不一致时，整个仓库 diff 全红</td><td>以项目配置为准，不要照抄模板</td></tr></tbody></table><p>验证方法：打开一个该语言文件 → <code>F1</code> → <code>Format Document</code> → 看状态栏右下角是否弹出&quot;没有安装格式化程序&quot;。 <strong>没有格式化程序 = 冲突已发生，不要靠&quot;我配了 formatter&quot;来判断。</strong></p><h3 id="_1-1-照抄-antfu-他人配置前的-隐藏前提-核对" tabindex="-1">1.1 照抄 antfu / 他人配置前的&quot;隐藏前提&quot;核对 <a class="header-anchor" href="#_1-1-照抄-antfu-他人配置前的-隐藏前提-核对" aria-label="Permalink to &quot;1.1 照抄 antfu / 他人配置前的&quot;隐藏前提&quot;核对&quot;">​</a></h3><p>一份名家配置能跑通，靠的是<strong>整套自洽</strong>，抄其中一半必然出错。核对三处：</p><ol><li><strong><code>prettier.enable: false</code> 的配套前提</strong>：antfu 原版注释原文是 <code>// I only use Prettier for manually formatting</code>，且他<strong>没有给任何语言设 <code>editor.defaultFormatter: esbenp.prettier-vscode</code></strong>——格式化交给 ESLint。 只抄 <code>prettier.enable: false</code>、又抄别处的 <code>defaultFormatter: prettier</code>，两套方案互相抵消。</li><li><strong><code>search.exclude</code> 的目录语义</strong>：antfu 原版排掉 <code>**/assets</code> / <code>**/public</code> / <code>**/*.svg</code>， 在他的项目里是产物；在 uni-app / 小程序项目里 <code>src/images</code> 下几百个 svg 是<strong>源码</strong>， 照抄会让全局搜索搜不到真实源码。按项目判定，不要照抄。</li><li><strong><code>workbench.preferredLightColorTheme</code> 必须是真浅色主题</strong>：antfu 填 <code>Vitesse Light</code>。 填深色主题（如 <code>One Dark Pro</code>）等于浅色模式不可用。</li></ol><p>取原始配置的方法（raw 链接常 404 或超时，jsDelivr 可用）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cdn.jsdelivr.net/gh/&amp;lt;owner&amp;gt;/&amp;lt;repo&amp;gt;@&amp;lt;branch&amp;gt;/&amp;lt;path&amp;gt;</span></span>
<span class="line"><span># 例：https://cdn.jsdelivr.net/gh/antfu/vscode-settings@main/.vscode/settings.json</span></span></code></pre></div><p>另外：<strong>fileNesting 不要全量照抄</strong>。antfu 的 <code>explorer.fileNesting.patterns</code> 有 60+ 条， 其中大量是 .NET / Rust / Svelte / LaTeX 规则。只留与本项目技术栈相关的 8~10 条， 否则大仓（900+ 文件）的文件树渲染会明显变慢。</p><h2 id="_1-2-改完会被-回退-的坑-注释与值必须同步改" tabindex="-1">1.2 改完会被&quot;回退&quot;的坑：注释与值必须同步改 <a class="header-anchor" href="#_1-2-改完会被-回退-的坑-注释与值必须同步改" aria-label="Permalink to &quot;1.2 改完会被&quot;回退&quot;的坑：注释与值必须同步改&quot;">​</a></h2><p>审查完的配置常被用户从备份粘贴回去，或手工改值时只改一半，产生<strong>注释与值矛盾</strong>：</p><ul><li><code>&quot;files.eol&quot;: &quot;\\r\\n&quot;</code> 后面却写着&quot;与 .editorconfig 的 lf 保持一致&quot;；</li><li><code>&quot;update.mode&quot;: &quot;none&quot;</code> 后面却写着&quot;已由 none 改为 manual&quot;。</li></ul><p>这类矛盾的危害是：下次读文件时不敢信注释，又不敢信值，只能重新查一遍。 <strong>收尾时必须做一次机械核对</strong>：全文搜注释里的 <code>[优化]</code> / <code>[修复]</code> / <code>[新增]</code>， 逐条确认注释描述与实际值一致。</p><h2 id="_2-清死配置-对当前-os-环境不生效-纯噪音" tabindex="-1">2. 清死配置（对当前 OS / 环境不生效，纯噪音） <a class="header-anchor" href="#_2-清死配置-对当前-os-环境不生效-纯噪音" aria-label="Permalink to &quot;2. 清死配置（对当前 OS / 环境不生效，纯噪音）&quot;">​</a></h2><ul><li>macOS only：<code>window.nativeTabs</code>、<code>terminal.integrated.*</code> 的部分 mac 专属项。</li><li>Linux only：<code>terminal.external.linuxExec</code>（已被 <code>terminal.integrated.profiles.*</code> 取代）。</li><li>主题类：<code>workbench.preferredLightColorTheme</code> 若填了深色主题，浅色模式等于不可用。</li><li>已被取代的旧键：优先看 <code>F1</code> → <code>Preferences: Open Settings (UI)</code> 里是否标注 Deprecated。</li><li>注释错位的行（注释描述的是另一项，复制模板时串行导致）：不修功能，但会误导后续维护，顺手改注释。</li></ul><h2 id="_3-安全红线-模板里最常见的三类" tabindex="-1">3. 安全红线（模板里最常见的三类） <a class="header-anchor" href="#_3-安全红线-模板里最常见的三类" aria-label="Permalink to &quot;3. 安全红线（模板里最常见的三类）&quot;">​</a></h2><ol><li><strong>明文密钥</strong>：翻译插件 / 图床插件的 <code>secret</code> / <code>accessKey</code> 常以明文写死。 处理：轮换密钥 → 改用环境变量或插件自带的密钥存储 → 从文件中删除。 （这类内容禁止进入任何共享知识库。）</li><li><code>security.workspace.trust.untrustedFiles: &quot;open&quot;</code> → 改 <code>&quot;prompt&quot;</code>。</li><li><code>update.mode: &quot;none&quot;</code> + <code>update.enableWindowsBackgroundUpdates: false</code> → 永不打补丁。 至少改 <code>&quot;manual&quot;</code>，保留手动确认但不再永久落后。</li></ol><h2 id="_4-性能项-大仓-单仓-500-文件的直接收益" tabindex="-1">4. 性能项（大仓 / 单仓 500+ 文件的直接收益） <a class="header-anchor" href="#_4-性能项-大仓-单仓-500-文件的直接收益" aria-label="Permalink to &quot;4. 性能项（大仓 / 单仓 500+ 文件的直接收益）&quot;">​</a></h2><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 建议新增，插在现有 files / search 段落内</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;typescript.tsserver.maxTsServerMemory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 默认 3072，大仓加到 4096~8192</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;search.followSymlinks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;files.watcherExclude&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;**/node_modules/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 已覆盖 pnpm 的 .pnpm 子目录</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;**/dist/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;**/.git/objects/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>反向检查：<code>search.exclude</code> 里从模板抄来的 <code>**/assets</code> / <code>**/public</code> / <code>**/*.svg</code><strong>在很多项目里是源码目录</strong>，会把真实源码从全局搜索里藏掉，按项目实际删掉。</p><h2 id="_5-被注释掉的-纯收益项-模板里默认关-逐个确认后打开" tabindex="-1">5. 被注释掉的&quot;纯收益项&quot;（模板里默认关，逐个确认后打开） <a class="header-anchor" href="#_5-被注释掉的-纯收益项-模板里默认关-逐个确认后打开" aria-label="Permalink to &quot;5. 被注释掉的&quot;纯收益项&quot;（模板里默认关，逐个确认后打开）&quot;">​</a></h2><ul><li><code>typescript.updateImportsOnFileMove.enabled: &quot;always&quot;</code>（同 <code>javascript.*</code>）—— 移动文件自动改引用路径。</li><li><code>typescript.preferences.preferTypeOnlyAutoImports: true</code> —— 自动导入类型时用 <code>import type</code>。</li><li><code>files.autoSave: &quot;afterDelay&quot;</code> —— 配合 AI agent 编辑，减少&quot;改了没存&quot;的落差。</li><li><code>editor.foldingStrategy: &quot;auto&quot;</code> —— 模板常写 <code>&quot;indentation&quot;</code>，对 TS / Vue 应改回 <code>auto</code>（语言感知）。</li></ul><h2 id="_6-新版设置项从哪里查-不要凭记忆" tabindex="-1">6. 新版设置项从哪里查（不要凭记忆） <a class="header-anchor" href="#_6-新版设置项从哪里查-不要凭记忆" aria-label="Permalink to &quot;6. 新版设置项从哪里查（不要凭记忆）&quot;">​</a></h2><p>唯一权威来源：<code>https://code.visualstudio.com/updates/v1_XXX</code> 的 <strong>Deprecated features and settings</strong> 与各章节的 <code>Setting: xxx</code> 标注。</p><p>截至 2026-09（1.130 ~ 1.134）仍值得主动打开的新项：</p><table tabindex="0"><thead><tr><th>设置</th><th>版本</th><th>作用</th></tr></thead><tbody><tr><td><code>chat.agentHost.enabled</code></td><td>1.130+</td><td>agent 跑在独立进程，同一会话可从多窗口连接</td></tr><tr><td><code>chat.assistedPermissions.enabled</code></td><td>1.130</td><td>模型评估工具调用风险，减少反复点确认</td></tr><tr><td><code>chat.tools.autoApprove</code></td><td>1.130</td><td>低风险工具自动放行</td></tr><tr><td><code>sessions.chatTimeline.display</code></td><td>1.134</td><td>会话右侧出现 prompt 时间轴，跳转历史提问</td></tr><tr><td><code>sessions.layout.singlePaneDetailPanel</code></td><td>1.134</td><td>单栏布局，会话详情与编辑器共用标签栏</td></tr><tr><td><code>dictation.enabled</code></td><td>1.131</td><td>内置离线语音输入（需下载模型，音频不出本机）</td></tr><tr><td><code>terminal.integrated.resizeDimensionsOverlay.enabled</code></td><td>1.131</td><td>关掉调整终端大小时的行列数浮层</td></tr><tr><td><code>workbench.editorAssociations</code></td><td>1.134</td><td>把 HTML 默认用内置浏览器打开</td></tr></tbody></table><p>编辑器侧常配的 AI 项：<code>editor.inlineSuggest.edits.enabled</code>（Next Edit Suggestions）、 <code>editor.inlineSuggest.edits.allowCodeShifting</code>、<code>editor.inlineSuggest.showToolbar: &quot;always&quot;</code>。</p><h2 id="_7-全局用户设置-vs-工作区设置" tabindex="-1">7. 全局用户设置 vs 工作区设置 <a class="header-anchor" href="#_7-全局用户设置-vs-工作区设置" aria-label="Permalink to &quot;7. 全局用户设置 vs 工作区设置&quot;">​</a></h2><p><strong>不要</strong>把用户 <code>settings.json</code> 整份复制进项目的 <code>.vscode/settings.json</code>：</p><ul><li>工作区设置覆盖用户设置，两份会长期漂移；</li><li>项目文件该进 git，个人偏好（字体、主题、密钥、终端）不该进；</li><li>正确分工：项目侧只放 <code>defaultFormatter</code> / <code>codeActionsOnSave</code> / <code>search.exclude</code> / <code>tsdk</code> 这类<strong>团队共识</strong>， 其余留在用户设置。</li></ul><p>判定：<code>diff</code> 两份文件，重复率 &gt; 80% 就是复制粘贴，把非项目相关的段落删掉。</p><h2 id="_8-执行顺序-15-25-分钟" tabindex="-1">8. 执行顺序（15~25 分钟） <a class="header-anchor" href="#_8-执行顺序-15-25-分钟" aria-label="Permalink to &quot;8. 执行顺序（15~25 分钟）&quot;">​</a></h2><ol><li>全局搜 <code>enable&quot;: false</code>，逐条确认其引用点没被打死（第 1 节）；</li><li>打开一个代表性文件跑一次 <code>Format Document</code> 验证；</li><li>搜 <code>secret</code> / <code>key</code> / <code>token</code> / <code>password</code>，处理明文凭证；</li><li>删死配置、改注释错位；</li><li>按第 4/5/6 节在<strong>原段落内</strong>插入新项，不重排；</li><li><code>F1</code> → <code>Developer: Reload Window</code>，逐项确认生效。</li></ol>`,36)])])}const g=t(a,[["render",i]]);export{h as __pageData,g as default};
